561	fn main() {
562	    let argv: Vec<String> = std::env::args().skip(1).collect();
563	    if !argv.is_empty() {
564	        // Direct CLI: `g-momonados factor_membrane factor <N> ...` runs the
565	        // membrane without entering the interactive REPL.
566	        let head = argv[0].as_str();
567	        if matches!(head, "factor_membrane" | "membrane" | "fmembrane") {
568	            let refs: Vec<&str> = argv[1..].iter().map(|x| x.as_str()).collect();
569	            println!("{}", factor_membrane::repl_factor_membrane(&refs));
570	            return;
571	        }
572	        if matches!(head, "shor_b4" | "shor_b4_membrane" | "key_membrane") {
573	            let refs: Vec<&str> = argv[1..].iter().map(|s| s.as_str()).collect();
574	            println!("{}", shor_b4_membrane::repl_shor_b4_membrane(&refs));
575	            return;
576	        }
577	        if matches!(head, "membrane_family" | "mfam") {
578	            let refs: Vec<&str> = argv[1..].iter().map(|s| s.as_str()).collect();
579	            println!("{}", membrane_family::repl_membrane(&refs));
580	            return;
581	        }
582	        if head == "native_numeral" {
583	            let refs: Vec<&str> = argv[1..].iter().map(|s| s.as_str()).collect();
584	            println!("{}", native_numeral_cli(&refs));
585	            return;
586	        }
587	        if head == "closure_nested" {
588	            let refs: Vec<&str> = argv[1..].iter().map(|s| s.as_str()).collect();
589	            println!("{}", closure_nested::repl_closure_nested(&refs));
590	            return;
591	        }
592	        if head == "tower_vox" {
593	            let refs: Vec<&str> = argv[1..].iter().map(|s| s.as_str()).collect();
594	            println!("{}", tower_vox::repl_tower_vox(&refs));
595	            return;
596	        }
597	        if head == "dqi_ambient" {
598	            let refs: Vec<&str> = argv[1..].iter().map(|s| s.as_str()).collect();
599	            dqi_ambient::repl_dqi_ambient(&refs);
600	            return;
601	        }
602	        // Same minimal shape as factor_membrane: a factoring build transforms
603	        // the contained value into factors and does nothing else, so this
604	        // never touches Kernel/boot — just winding_period::factor itself.
605	        if matches!(head, "winding" | "wperiod") {
606	            let sub = argv.get(1).map(|s| s.as_str()).unwrap_or("");
607	            if sub == "factor" {
608	                let n: u64 = argv.get(2).and_then(|s| s.parse().ok()).unwrap_or(0);
609	                let tries: u32 = argv.get(3).and_then(|s| s.parse().ok()).unwrap_or(12);
610	                let seed: u64 = argv.get(4).and_then(|s| s.parse().ok()).unwrap_or(0x9E37_79B9_7F4A_7C15);
611	                match winding_period::factor(n, tries, seed) {
612	                    Some((a, r, p, q)) => println!("FACTORED {} = {} × {}  (a={}, r={})  p·q==N: {}", n, p, q, a, r, p * q == n),
613	                    None => println!("factor({}): no factor in {} tries", n, tries),
614	                }
615	                return;
616	            }
617	            if sub == "order" {
618	                let a: u64 = argv.get(2).and_then(|s| s.parse().ok()).unwrap_or(0);
619	                let n: u64 = argv.get(3).and_then(|s| s.parse().ok()).unwrap_or(0);
620	                match winding_period::winding_order(a, n) {
621	                    Some(r) => println!("winding_order({}, {}) = {}  (a^r == 1 mod N, the closure winding)", a, n, r),
622	                    None => println!("winding_order({}, {}): no period (a not in the unit group)", a, n),
623	                }
624	                return;
625	            }
626	        }
627	        // The nested hosted executable vessel reads its own argv in admit();
628	        // route the relation flags to it rather than the REPL seed.
629	        if matches!(head, "--selector-relation" | "--selector-relation-stdin") {
630	            gpu_kernel::run_hosted_executable();
631	            return;
632	        }
633	        // Every other command is a REPL verb (`shor-qft run 7 15 8`,
634	        // `shor-qft run 7 15 8`, …) — none of them worth hand-adding a fast
635	        // path for one at a time. Run the real boot, then this one line as
636	        // if typed at the prompt, then quit: every command on every menu is
637	        // reachable this way, through argv, with no stdin pipe needed.
638	        let mut seed: alloc::collections::VecDeque<String> = alloc::collections::VecDeque::new();
639	        seed.push_back(argv.join(" "));
640	        seed.push_back("quit".to_string());
641	        kmain_seeded(seed);
642	        return;
643	    }
644	    gpu_kernel::run_hosted_executable()
645	}
