647	#[cfg(feature = "hosted")]
648	fn native_numeral_cli(args: &[&str]) -> String {
649	    if args.is_empty() { return native_numeral::help(); }
650	    match args[0] {
651	        "encode" if args.len() > 1 => native_numeral::encode(args[1]),
652	        "factor" | "factor_decimal" if args.len() > 1 => native_numeral::factor_decimal(args[1]),
653	        "unbraid" if args.len() > 1 => {
654	            let cap = args.get(2).and_then(|s| s.parse::<u64>().ok()).unwrap_or(u64::MAX);
655	            native_numeral::unbraid_report(args[1], cap)
656	        }
657	        "decompose" if args.len() > 1 => native_numeral::decompose_report(args[1]),
658	        _ => native_numeral::help(),
659	    }
660	}
661	
662	fn kmain() {
663	    kmain_seeded(alloc::collections::VecDeque::new())
664	}
665	
666	/// Same boot, with `seed` commands run first (see `repl::repl_seeded`) — every
667	/// REPL command reachable non-interactively, through the real boot sequence,
668	/// with no OS-level stdin pipe needed and no per-command dispatch to hand-add.
669	pub fn kmain_seeded(seed: alloc::collections::VecDeque<String>) {
670	    serial::init();
671	
672	    // Hosted: the host owns the IDT, so there is no PIT and no PIC remap. The
673	    // boot line states only the hardware this build actually touches.
674	    interrupts::init(100);
675	    #[cfg(not(feature = "hosted"))]
676	    sprintln!("{}[boot]{} Interrupts online — PIT 100Hz, PIC remapped", style::muted(), style::reset());
677	    #[cfg(feature = "hosted")]
678	    sprintln!("{}[boot]{} Interrupts: none — the host owns the IDT, no periodic slot", style::muted(), style::reset());
679	
680	    {
681	        let (used, total) = heap_used();
682	        #[cfg(not(feature = "hosted"))]
683	        sprintln!("{}[boot]{} Heap: {}MB static BSS", style::muted(), style::reset(), total / (1024 * 1024));
684	        #[cfg(feature = "hosted")]
685	        sprintln!("{}[boot]{} Heap: host allocator, {} bytes counted, {}MB declared budget", style::muted(), style::reset(),
686	                  used, total / (1024 * 1024));
687	        let _ = used;
688	    }
689	
690	    let mut k = Kernel::new();
691	    k.boot();
692	    catalog::catalog_init();
693	    sprintln!("{}[boot]{} IG Catalog: {} entries loaded", style::muted(), style::reset(), catalog::catalog_size());
694	    sprintln!("{}[boot]{} Kernel online — graph execution, token-arity driven", style::muted(), style::reset());
695	    // ── ⊙-ordinal faithfulness guard (Track B) ──
696	    sprintln!("{}[boot]{} Canonical ordinal check...", style::muted(), style::reset());
697	    match canonical_ordinal::verify_canonical_ordinals() {
698	        (true, _) => sprintln!("{}[boot]{} Ordinal faithfulness: {}all 44 values match Lean canonical{}",
699	            style::muted(), style::reset(), style::verdict_t(), style::reset()),
700	        (false, why) => {
701	            sprintln!("{}[boot]{} ⚠ ORDINAL DRIFT DETECTED: {}", style::muted(), style::reset(), why);
702	            sprintln!("{}[boot]{} Kernel will NOT proceed — ordinal drift is a structural integrity violation.", style::muted(), style::reset());
703	            sprintln!("{}[boot]{} Regenerate canonical_ordinal.rs from CanonicalOrdinalFaithfulness.lean", style::muted(), style::reset());
704	            loop { unsafe { core::arch::asm!("hlt", options(nostack, nomem, preserves_flags)); } }
705	        }
706	    }
707	    // ── Clay closure/resistance status (Track C) ──
708	    sprintln!("{}[boot]{} Clay Millennium status: {} closed, {} one-bump-short, {} unclosed", style::muted(), style::reset(),
709	        clay_status::clay_summary().0, clay_status::clay_summary().1, clay_status::clay_summary().2);
710	    // Every figure on this line is read from the constants that define it, so
711	    // the banner cannot assert a structure the code no longer carries.
712	    sprintln!("{}[boot]{} SIC-POVM d={}: Crystal-forced (dual lattice), Shavian count {}={}², WH group |orbit|={}", style::muted(), style::reset(),
713	        sic_povm::TOTAL_PRIMS, sic_povm::SHAVIAN_COUNT,
714	        sic_povm::SHAVIAN_ROOT, sic_povm::WH_GROUP_ORDER);
715	    // ── Frobenius unification self-verification (Track E) ──
716	    sprintln!("{}[boot]{} Frobenius identity check...", style::muted(), style::reset());
717	    let (frob_ham, frob_dist) = frobenius_unify::boot_summary();
718	    if frob_ham == 0 {
719	        sprintln!("{}[boot]{} Frobenius identity: KERNEL IS FROBENIUS FIXED POINT — d=0 ✓", style::muted(), style::reset());
720	    } else {
721	        sprintln!("{}[boot]{} Frobenius identity: hamming={}, weighted={:.4} — kernel is grammar operationalized", style::muted(), style::reset(),
722	            frob_ham, frob_dist);
723	    }
724	
725	    sprintln!("{}[boot]{} Bootstrap: IMSCRIB→AREV→FSPLIT→AFWD→FFUSE→CLINK→IFIX→IMSCRIB (cyclic)", style::muted(), style::reset());
726	    sprintln!("{}[boot]{} Fibonacci anyon QC: algebra verified = {}", style::muted(), style::reset(), fibonacci_qc::verify_all());
727	    // ── Kernel torus winding display (Track A) ──
728	    let torus_map = kernel_torus::TorusMap::new(&kernel_torus::agent_loop_program());
729	    kernel_torus::display_banner(&torus_map);
730	    sprintln!("{}[boot]{} Crystal FS: {} addresses", style::muted(), style::reset(), TOTAL);
731	    sprintln!("{}[boot]{} {} total programs (I–XXIX): 12 canonical + {} continuous + {} novel + {} shunted", style::muted(), style::reset(),
732	        canonical_count() + continuous_count() + novel_count() + shunted_count(),
733	        continuous_count(), novel_count(), shunted_count());
734	    sprintln!();
735	
736	    print_banner();
737	    
738	    // Start live corner HUD (hosted build)
739	    #[cfg(feature = "hosted")]
740	    live_hud::start_hud();
741	    
742	    repl::repl_seeded(&mut k, seed);
743	
744	    // ── Shutdown: write to QEMU isa-debug-exit port (0xf4).
745	    // Value 0x10 → QEMU exits with status 0.
746	    // On real hardware or without the device, falls through to HLT.
747	    sprintln!("[SHUTDOWN] μ∘δ=id. Goodbye.");
748	
749	    // `out` and `hlt` are privileged. On bare metal they are the QEMU
750	    // debug-exit device and the idle halt; in a userspace process they are a
751	    // general protection fault, which is what made the hosted build segfault on
752	    // quit. A host does not need a debug-exit device emulated at it -- it
753	    // exits.
754	    #[cfg(not(feature = "hosted"))]
755	    unsafe {
756	        core::arch::asm!(
757	            "out dx, eax",
758	            in("dx") 0xf4_u16,
759	            in("eax") 0x10_u32,
760	            options(nomem, nostack, preserves_flags)
761	        );
762	    }
763	    #[cfg(not(feature = "hosted"))]
764	    loop { unsafe { core::arch::asm!("hlt", options(nostack, nomem, preserves_flags)); } }
765	
766	    #[cfg(feature = "hosted")]
767	    return;
768	}
