770	fn print_banner() {
771	    // The mark, the name, then what it is. This is the one screen where the
772	    // reader has no context yet, so it leads with the object and not the
773	    // feature list.
774	    sprintln!();
775	    sprintln!("   {}⊙{}   {}G-mOMonadOS{}", style::glyph(), style::reset(),
776	              style::heading(), style::reset());
777	    #[cfg(not(feature = "hosted"))]
778	    sprintln!("   {}the self-imscribing bare-metal kernel{}", style::muted(), style::reset());
779	    #[cfg(feature = "hosted")]
780	    sprintln!("   {}GPU-native build, mOMonadOS ported to run via CUDA{}", style::muted(), style::reset());
781	    sprintln!("   {}μ∘δ = id{}", style::accent(), style::reset());
782	    sprintln!();
783	    sprintln!("   {}Frobenius core · Belnap FOUR · crystal FS · graph execution{}",
784	              style::muted(), style::reset());
785	    sprintln!();
786	    sprintln!("   {}help{} for commands, {}?{} for the menu, Tab completes.",
787	              style::key(), style::reset(), style::key(), style::reset());
788	    sprintln!();
789	}
