791	// ─── Panic ────────────────────────────────────────────────────
792	
793	#[cfg(not(feature = "hosted"))]
794	#[panic_handler]
795	fn panic(info: &PanicInfo) -> ! {
796	    serial::write_str("\n[PANIC] ");
797	    sprint!("{}", info.message());
798	    sprintln!();
799	    loop { unsafe { core::arch::asm!("hlt", options(nostack, nomem, preserves_flags)); } }
800	}
801	
802	/// Report heap exhaustion ourselves.
803	///
804	/// The default handler reaches the panic through `__rust_alloc_error_handler`,
805	/// an internal symbol that takes the size and align as loose integers. Under
806	/// this build — `build-std` with fat LTO — that call arrives with a size of
807	/// zero however large the failed request was: an allocation of 1264 bytes
808	/// against 552 free reported itself as "memory allocation of 0 bytes failed",
809	/// which sent every reader hunting for a zero-size bug that does not exist.
810	///
811	/// Taking the `Layout` here reads it directly instead of through that symbol,
812	/// and the writes below never allocate, which matters when the reason we are
813	/// here is that allocation just failed.
814	#[cfg(not(feature = "hosted"))]
815	#[alloc_error_handler]
816	fn alloc_error(layout: Layout) -> ! {
817	    let (used, total) = heap_used();
818	    serial::write_str("\n[PANIC] heap exhausted — wanted ");
819	    serial::write_dec(layout.size());
820	    serial::write_str(" bytes (align ");
821	    serial::write_dec(layout.align());
822	    serial::write_str("), ");
823	    serial::write_dec(total.saturating_sub(used));
824	    serial::write_str(" free of ");
825	    serial::write_dec(total);
826	    serial::write_str("\n");
