126	    let mut history = History::new();
127	    let mut ctx_stack = ContextStack::new();
128	    let mut ask_paste = crate::ask::AskPaste::new();
129	    // Held incomplete bigint verb (`gpu_ecm bsgs`, …); digit-only lines extend it.
